import re, os, collections
decls={}
files=[]
for root,dirs,fs in os.walk('.'):
    dirs[:]=[d for d in dirs if d not in ('.git','node_modules','dist','gen')]
    for f in fs:
        if f.endswith('.go'):
            p=os.path.join(root,f)[2:]
            files.append(p)
src={p:open(p,encoding='utf8',errors='ignore').read() for p in files}
dre=re.compile(r'^func\s+(?:\([^)]*\)\s*)?([A-Z_a-z]\w*)\s*[\(\[]',re.M)
for p in files:
    if p.startswith('internal/') and not p.endswith('_test.go'):
        for m in dre.finditer(src[p]):
            decls.setdefault(m.group(1),[]).append((p,src[p][:m.start()].count('\n')+1))
counts=collections.Counter()
nontest=collections.Counter()
for name in decls:
    cre=re.compile(r'(?<![\w.])(?:\w+\.)?'+re.escape(name)+r'\s*\(')
    for p in files:
        for line in src[p].split('\n'):
            if line.lstrip().startswith('func ') and re.search(r'func\s+(?:\([^)]*\)\s*)?'+re.escape(name)+r'\s*[\(\[]',line):
                continue
            n=len(cre.findall(line))
            if n:
                counts[name]+=n
                if not p.endswith('_test.go'): nontest[name]+=n
for name,c in counts.most_common(25):
    print(c, nontest[name], name, decls[name][:2])
EOF

